32	/// Recordings kept per interface and depth. A component whose state differs from all of them resolves the chain itself.
33	const RECORDINGS_PER_KEY: usize = 4;
34	
35	/// The recordings of one run, by key and depth. A watch revision builds a new context and so starts empty.
36	pub(crate) struct Memo<T> {
37	    recordings: dashmap::DashMap<(CompactString, u8), Vec<Arc<Recording<T>>>, rustc_hash::FxBuildHasher>,
38	    /// Recordings that read more than this are not kept: replaying one appends all of its reads to every enclosing
39	    /// recording, which costs more than resolving a small type again.
40	    max_reads: usize,
41	    /// The keys being resolved right now, and by which thread, so that threads that need the same one wait for it
42	    /// instead of each resolving it (Chakra's components all start from the same few thousand style props).
43	    flights: dashmap::DashMap<(CompactString, u8), Arc<Flight>, rustc_hash::FxBuildHasher>,
44	    /// Which thread each waiting thread waits for, to refuse a wait that would close a cycle.
45	    waiting: dashmap::DashMap<ThreadId, ThreadId, rustc_hash::FxBuildHasher>,
46	}
47	
48	/// One thread's resolution of a key, which others wait on.
49	struct Flight {
50	    leader: ThreadId,
51	    done: Mutex<bool>,
52	    finished: Condvar,
53	}
54	
55	/// The longest a thread waits for another's resolution. Mutually recursive types can make two threads wait on each
56	/// other past what the waits-for check sees; the waiter then resolves the key itself.
57	const MAX_WAIT: Duration = Duration::from_millis(250);
58	
59	impl Flight {
60	    fn wait(&self) {
61	        let mut done = self.done.lock().unwrap_or_else(PoisonError::into_inner);
62	        while !*done {
63	            let (guard, timeout) = self.finished.wait_timeout(done, MAX_WAIT).unwrap_or_else(PoisonError::into_inner);
64	            done = guard;
65	            if timeout.timed_out() {
66	                break;
67	            }
68	        }
69	    }
70	}
71	
72	/// Ends the leader's flight when the resolution returns, or unwinds.
73	struct FlightGuard<'a, T> {
74	    memo: &'a Memo<T>,
75	    key: (CompactString, u8),
76	    flight: Arc<Flight>,
77	}
78	
79	impl<T> Drop for FlightGuard<'_, T> {
80	    fn drop(&mut self) {
81	        self.memo.flights.remove_if(&self.key, |_, flight| Arc::ptr_eq(flight, &self.flight));
82	        *self.flight.done.lock().unwrap_or_else(PoisonError::into_inner) = true;
83	        self.flight.finished.notify_all();
84	    }
85	}
