87	impl<T> Default for Memo<T> {
88	    fn default() -> Self {
89	        Self::with_max_reads(usize::MAX)
90	    }
91	}
92	
93	impl<T> Memo<T> {
94	    pub(crate) fn with_max_reads(max_reads: usize) -> Self {
95	        Self { recordings: Default::default(), max_reads, flights: Default::default(), waiting: Default::default() }
96	    }
97	}
