99	/// The chains of interfaces, by scoped key.
100	pub(crate) type InterfaceChains = Memo<ResolvedChain>;
101	
102	/// The types of named references, by consuming file, name and arguments.
103	pub(crate) type NamedResults = Memo<PropType>;
104	
105	/// One resolution and everything needed to decide whether another state would repeat it.
106	struct Recording<T> {
107	    value: T,
108	    /// How many more named types the resolution had in progress at its deepest than when it started: a state already
109	    /// that deep would have hit the nesting limit where this one did not.
110	    reach: usize,
111	    /// Chunks of diagnostics the resolution reported, its own distinct ones first; replays share them.
112	    shared: Vec<Arc<[Diagnostic]>>,
113	    /// The first read of each key, which is what the state held on entry, and the state's own additions.
114	    reads: StateReads,
115	    named_unevaluated: bool,
116	    deps: Dependencies,
117	    /// `ResolveState::expand_all` while recording: a chain with collapsed sources must not answer an expanding state.
118	    expand_all: bool,
119	    /// `ResolveState::omitted` while recording: which sources collapse depends on it.
120	    omitted: Option<Arc<rustc_hash::FxHashSet<String>>>,
121	    keys_only: bool,
122	    /// The depth the resolution started at, and how much deeper than that it checked against the limit. Depth decides
123	    /// the result only through the limit and `depth > 0` (collapse, which the key holds), so a state that
124	    /// starts at another depth, shallower or deeper, resolves the same while its deepest check stays within the limit.
125	    entry_depth: u8,
126	    depth_reach: u8,
127	    /// A check hit the limit: the result holds a depth-exceeded stop, which only the same starting depth reproduces.
128	    depth_fired: bool,
129	}
130	
131	/// Keep the first read of each key: what the state held on entry. A later read may see the resolution's own
132	/// additions, and an enclosing recording only needs the first one either.
133	fn first_reads<K: Clone + Eq + Hash, V>(reads: Vec<(K, V)>) -> Vec<(K, V)> {
134	    let mut seen: FxHashSet<K> = FxHashSet::default();
135	    reads.into_iter().filter(|(key, _)| seen.insert(key.clone())).collect()
136	}
137	
138	/// Each distinct diagnostic once, in the order first reported.
139	fn distinct(diagnostics: &[Diagnostic]) -> Vec<Diagnostic> {
140	    let mut seen: FxHashSet<&Diagnostic> = FxHashSet::default();
141	    diagnostics.iter().filter(|diagnostic| seen.insert(diagnostic)).cloned().collect()
142	}
