144	impl<T: Clone> Recording<T> {
145	    /// Whether `state` and `mapping` give the same answer to every read the recorded resolution made.
146	    fn applies_to(&self, state: &ResolveState, mapping: Option<&ComponentMapping>, depth: u8) -> bool {
147	        let reads = &self.reads;
148	        let depth_fits = if self.depth_fired {
149	            depth == self.entry_depth
150	        } else {
151	            usize::from(depth) + usize::from(self.depth_reach) <= usize::from(MAX_DEPTH)
152	        };
153	        depth_fits
154	            && state.named_in_progress.len() + self.reach <= MAX_NAMED_NESTING
155	            && self.expand_all == state.expand_all
156	            && self.omitted == state.omitted
157	            && self.keys_only == state.keys_only
158	            && reads.visited.iter().all(|(key, present)| state.visited.contains(key) == *present)
159	            && reads.named.iter().all(|(key, present)| state.named_in_progress.contains(key) == *present)
160	            && (!reads.needs_empty_scope || state.binds_nothing())
161	            && reads.in_scope.iter().all(|(name, present)| state.binds(name) == *present)
162	            && reads.body_reads.iter().all(|(name, read)| {
163	                mapping.is_some_and(|mapping| crate::types::global::body_reads(mapping, name) == *read)
164	            })
165	            && reads.defaults.iter().all(|(name, found)| {
166	                mapping.is_some_and(|mapping| {
167	                    mapping.param_defaults.get(name.as_str()).map(|d| (d.value.as_str(), d.computed))
168	                        == found.as_ref().map(|(value, computed)| (value.as_str(), *computed))
169	                })
170	            })
171	    }
172	
173	    /// Apply the recorded resolution's effects to `state` and return its value.
174	    fn replay(&self, state: &mut ResolveState, depth: u8) -> T {
175	        state.named_high = state.named_high.max(state.named_in_progress.len() + self.reach);
176	        state.depth_high = state.depth_high.max(depth.saturating_add(self.depth_reach));
177	        if let Some(reads) = state.reads.as_mut() {
178	            reads.append(&self.reads, true, true);
179	        }
180	        state.visited.extend(self.reads.visited_added.iter().copied());
181	        state.shared_diagnostics.extend(self.shared.iter().cloned());
182	        state.named_unevaluated |= self.named_unevaluated;
183	        super::deps::replay(&self.deps);
184	        self.value.clone()
185	    }
186	}
