188	impl<T: Clone> Memo<T> {
189	    /// Add to `into` the recordings whose dependencies `keep` accepts, given the file declaring their interface.
190	    pub(super) fn copy_into(&self, into: &Memo<T>, keep: &impl Fn(&Dependencies, &str) -> bool) {
191	        for entry in self.recordings.iter() {
192	            // The key is the interface's `file:name`; a file path may hold a `:` itself, so split from the right.
193	            let file = entry.key().0.rsplit_once(':').map_or("", |(file, _)| file);
194	            let kept: Vec<Arc<Recording<T>>> = entry.value().iter().filter(|r| keep(&r.deps, file)).cloned().collect();
195	            if !kept.is_empty() {
196	                into.recordings.insert(entry.key().clone(), kept);
197	            }
198	        }
199	    }
