201	    /// The value for `key` reached at `depth`: replayed from a recording that applies to `state`, or resolved by
202	    /// `resolve` and recorded.
203	    pub(super) fn get_or_resolve(
204	        &self,
205	        key: &str,
206	        depth: u8,
207	        state: &mut ResolveState,
208	        mapping: Option<&ComponentMapping>,
209	        resolve: impl FnOnce(&mut ResolveState) -> T,
210	    ) -> T {
211	        // The modes never answer each other, so they must not compete for one key's recordings. Depth enters the key
212	        // only as whether it is the component's own props type (0): a source reached deeper collapses (collapse), one
213	        // reached at 0 does not. The rest of what depth decides, the limit, a recording checks in `applies_to`.
214	        let mode = u8::from(depth > 0) | (u8::from(state.expand_all) << 6) | (u8::from(state.keys_only) << 7);
215	        let map_key = (CompactString::from(key), mode);
216	        let find = |state: &ResolveState| {
217	            self.recordings
218	                .get(&map_key)
219	                .and_then(|recordings| recordings.iter().find(|r| r.applies_to(state, mapping, depth)).cloned())
220	        };
221	        if let Some(recording) = find(state) {
222	            return recording.replay(state, depth);
223	        }
224	
225	        // Another thread already resolving this key finishes it for everyone; wait for it, then look again.
226	        let me = std::thread::current().id();
227	        let _flight = match self.flights.entry(map_key.clone()) {
228	            dashmap::mapref::entry::Entry::Occupied(entry) => {
229	                let flight = Arc::clone(entry.get());
230	                drop(entry);
231	                if flight.leader != me && !self.would_wait_in_a_cycle(me, flight.leader) {
232	                    self.waiting.insert(me, flight.leader);
233	                    flight.wait();
234	                    self.waiting.remove(&me);
235	                    if let Some(recording) = find(state) {
236	                        return recording.replay(state, depth);
237	                    }
238	                }
239	                None
240	            }
241	            dashmap::mapref::entry::Entry::Vacant(entry) => {
242	                let flight = Arc::new(Flight { leader: me, done: Mutex::new(false), finished: Condvar::new() });
243	                entry.insert(Arc::clone(&flight));
244	                Some(FlightGuard { memo: self, key: map_key.clone(), flight })
245	            }
246	        };
247	
248	        // Record: a fresh read log for this resolution, merged into the enclosing one afterwards.
249	        let entry_nesting = state.named_in_progress.len();
250	        let enclosing_high = std::mem::replace(&mut state.named_high, entry_nesting);
251	        let enclosing_depth_high = std::mem::replace(&mut state.depth_high, depth);
252	        let enclosing = state.reads.replace(Box::default());
253	        let entry_unevaluated = std::mem::take(&mut state.named_unevaluated);
254	        let diagnostics_before = state.diagnostics.len();
255	        let shared_before = state.shared_diagnostics.len();
256	        let (value, deps) = super::deps::capturing(|| resolve(state));
257	        let high = state.named_high;
258	        state.named_high = enclosing_high.max(high);
259	        let depth_high = state.depth_high;
260	        state.depth_high = enclosing_depth_high.max(depth_high);
261	        let mut reads = *state.reads.take().unwrap_or_default();
262	        reads.visited = first_reads(reads.visited);
263	        reads.named = first_reads(reads.named);
264	        reads.in_scope = first_reads(reads.in_scope);
265	        reads.defaults = first_reads(reads.defaults);
266	        reads.body_reads = first_reads(reads.body_reads);
