291	            value: value.clone(),
292	            reach: high.saturating_sub(entry_nesting),
293	            shared,
294	            named_unevaluated,
295	            deps,
296	            reads,
297	            expand_all: state.expand_all,
298	            omitted: state.omitted.clone(),
299	            keys_only: state.keys_only,
