310	    /// exit-code flip this project has already fixed once (see the
311	    /// resolver's discarded-return-type-resolution fix).
312	    pub fn save_to_disk(&self) -> Option<Diagnostic> {
313	        if !self.persistent || !self.dirty.load(std::sync::atomic::Ordering::Relaxed) {
314	            return None;
315	        }
316	        self.try_save().err().map(|reason| Diagnostic {
317	            severity: DiagnosticSeverity::Info,
318	            message: format!("Failed to persist the DTS cache to '{}': {reason}", self.cache_dir),
319	            file: None,
320	            line: None,
321	            column: None,
322	            help: Some("Check that the cache directory is writable. Extraction still succeeded; only caching for the next run was affected.".into()),
323	            code: DiagnosticCode::IoError,
324	            affects: Vec::new(),
325	        })
