328	    fn try_save(&self) -> Result<(), String> {
329	        std::fs::create_dir_all(self.cache_dir.as_std_path()).map_err(|e| e.to_string())?;
330	
331	        // Collect into a serializable form.
332	        let entries: Vec<(SerializableCacheKey, SourceData)> =
333	            self.store.iter().map(|r| (SerializableCacheKey::from(r.key()), r.value().clone())).collect();
334	
335	        let header = CacheHeader::current();
336	        let mut bytes = rmp_serde::to_vec(&header).map_err(|e| e.to_string())?;
337	        bytes.extend(rmp_serde::to_vec(&entries).map_err(|e| e.to_string())?);
