339	        write_atomic(&self.cache_dir, DATA_FILE, &bytes)?;
340	
341	        // For inspection only; loading trusts the payload's own header.
342	        let manifest = serde_json::json!({
343	            "schema": header.schema,
344	            "version": header.version,
345	            "fingerprint": header.fingerprint,
346	            "entry_count": entries.len(),
347	        });
348	        let manifest_json = serde_json::to_string_pretty(&manifest).map_err(|e| e.to_string())?;
349	        write_atomic(&self.cache_dir, "manifest.json", manifest_json.as_bytes())?;
