357	    /// Builds the cache key from the file's path and a hash of its content —
358	    /// see `CacheKey`'s doc comment for why this replaced mtime+size.
359	    fn key_for(&self, path: &Utf8Path, content: &str) -> CacheKey {
360	        CacheKey { path: path.to_owned(), content_hash: hash_content(content) }
361	    }
362	}
