364	/// Write via temp file + rename so readers never see a partial file. The temp name is unique per process and call:
365	/// processes sharing a cache dir (CLI + Vite plugin, parallel tests) would otherwise clobber each other's temp file.
366	fn write_atomic(dir: &Utf8Path, name: &str, bytes: &[u8]) -> Result<(), String> {
367	    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
368	    let seq = SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
369	    let tmp_path = dir.join(format!("{name}.{}.{seq}.tmp", std::process::id()));
370	    let final_path = dir.join(name);
371	
372	    let result = std::fs::write(tmp_path.as_std_path(), bytes)
373	        .and_then(|()| std::fs::rename(tmp_path.as_std_path(), final_path.as_std_path()));
374	    if result.is_err() {
375	        std::fs::remove_file(tmp_path.as_std_path()).ok();
376	    }
377	    result.map_err(|e| e.to_string())
378	}
