1	//! The heap budget of a whole-project run ([`crate::resolve`] and the calls beside it, which `extract` makes).
2	//!
3	//! A converted type is a tree the run builds in its own heap, and a type that expands to millions of members (a style
4	//! system declared in the project's own source, with hundreds of properties each over a hundred conditions) builds
5	//! tens of GiB of them, most of it copies of trees the converter recalls from its memo between two requests. The budget
6	//! is the safety net under every such shape: the run reads the heap before each component and every [`STEPS_PER_READ`]
7	//! steps (a checker request, or a type the converter converts or recalls), and once the heap is past the budget it
8	//! takes no further step: the conversion in flight stops at its next one. Every component it has not answered by then, the one in flight included, keeps its
9	//! structural result, and one warning says how many and why. Which components those are depends on how far each lane
10	//! had got, so past the budget the output depends on timing; a run that stays under it is unchanged.
11	//!
12	//! The heap is what mimalloc, the allocator of the CLI and of the native binding, has committed
13	//! (`mi_process_info`): the converter's trees, its memo and the merged props, all the Rust memory of the run. It
14	//! leaves out the checker's arenas, a range of their own that [`OnDemand`](crate::OnDemand)'s bound reads. A process
15	//! whose allocator is not mimalloc reads only mimalloc's own small commit, and so never reaches the budget.
16	
17	use std::sync::OnceLock;
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
21	
22	use crate::rpc::CallError;
23	
24	/// The most a budget derived from the machine allows: 8 GiB, about seven times the 1.1 GiB the largest corpus measured
25	/// commits (Mantine's core, shadcn, `gate-large`; docs/type-checker-integration.md).
26	pub const MAX_HEAP_BUDGET: u64 = 8 << 30;
27	
28	/// How many steps (checker requests, and types converted or recalled from the memo) a run takes between two reads of
29	/// the heap, besides the read before each component. A read costs about 0.9 µs (`mi_process_info`, measured over
30	/// 100,000 reads on an M-series Mac), so a read every 32 steps is about 30 ns a step.
31	const STEPS_PER_READ: u64 = 32;
32	
33	/// How large a whole-project run's heap may grow before it stops asking the checker (the module's documentation).
34	#[derive(Debug, Clone, Copy)]
35	pub struct HeapBudget {
36	    bytes: u64,
37	    meter: fn() -> u64,
38	}
39	
40	impl HeapBudget {
41	    /// The budget of this machine: 60% of the memory this process may use, at most [`MAX_HEAP_BUDGET`] (that, where
42	    /// the memory cannot be read). The memory is the physical memory, or on Linux the memory limit of the process's
43	    /// cgroup (a container's, a CI job's) when that is lower. 60%, because the heap is not all the process holds (the
44	    /// checker's arenas, the structural result, the JSON being written, and in the binding the host's own heap), and a
45	    /// run past that memory swaps or is killed rather than finishing.
46	    pub fn machine() -> Self {
47	        let usable = match (physical_memory(), cgroup_limit()) {
48	            (Some(physical), Some(limit)) => Some(physical.min(limit)),
49	            (physical, limit) => physical.or(limit),
50	        };
51	        Self::new(usable.map_or(MAX_HEAP_BUDGET, |bytes| (bytes / 10 * 6).min(MAX_HEAP_BUDGET)))
52	    }
53	
54	    /// A budget of `bytes` of mimalloc's committed heap.
55	    pub fn new(bytes: u64) -> Self {
56	        Self { bytes, meter: committed }
57	    }
58	
59	    /// A budget of `bytes` as `meter` reads the heap: tests stand in a meter whose readings they choose.
60	    #[cfg(test)]
61	    pub(crate) fn metered(bytes: u64, meter: fn() -> u64) -> Self {
62	        Self { bytes, meter }
63	    }
64	
65	    /// The bytes the budget allows.
66	    pub fn bytes(&self) -> u64 {
67	        self.bytes
68	    }
69	}
70	
71	/// The bytes mimalloc has committed for the whole process, as it counts them.
72	pub(crate) fn committed() -> u64 {
73	    let mut commit = 0usize;
74	    let null = std::ptr::null_mut();
75	    // SAFETY: `mi_process_info` writes each out-parameter that is not null and reads nothing else; `commit` outlives
76	    // the call.
77	    #[allow(unsafe_code)]
78	    unsafe {
79	        libmimalloc_sys::mi_process_info(null, null, null, null, null, &raw mut commit, null, null);
80	    }
81	    commit_bytes(commit)
82	}
83	
84	/// mimalloc's commit counter is signed inside: frees that other threads return before the allocation they match makes it
85	/// read a few MiB below zero, which as a `usize` is nearly 2^64 and would put the run past any budget at once.
86	fn commit_bytes(raw: usize) -> u64 {
87	    u64::try_from(raw as isize).unwrap_or(0)
88	}
89	
90	/// The machine's physical memory in bytes.
91	#[cfg(unix)]
92	fn physical_memory() -> Option<u64> {
93	    // SAFETY: `sysconf` reads a system constant and has no other effect.
94	    #[allow(unsafe_code)]
95	    let (pages, size) = unsafe { (libc::sysconf(libc::_SC_PHYS_PAGES), libc::sysconf(libc::_SC_PAGESIZE)) };
96	    u64::try_from(pages).ok()?.checked_mul(u64::try_from(size).ok()?)
97	}
98	
99	/// Elsewhere the machine's memory is not read.
100	#[cfg(not(unix))]
101	fn physical_memory() -> Option<u64> {
102	    None
103	}
104	
105	/// The lowest memory limit of the cgroups this process is in, from its own (`/proc/self/cgroup`) up to the root of the
106	/// hierarchy's mount (`/proc/self/mountinfo`), in bytes. None when no limit is set, and equally when nothing can be
107	/// found: the files unreadable, no cgroup mount listed, or the process's cgroup outside what the mount shows. The
108	/// caller then falls back to the host's physical memory, so a limit that cannot be read is not enforced.
109	#[cfg(target_os = "linux")]
110	fn cgroup_limit() -> Option<u64> {
111	    let own = std::fs::read_to_string("/proc/self/cgroup").ok()?;
112	    let mounts = std::fs::read_to_string("/proc/self/mountinfo").ok()?;
113	    limit_files(&own, &mounts)
114	        .iter()
115	        .filter_map(|file| std::fs::read_to_string(file).ok())
116	        .filter_map(|text| parse_limit(&text))
117	        .min()
118	}
119	
120	/// Only Linux has cgroups.
121	#[cfg(not(target_os = "linux"))]
122	fn cgroup_limit() -> Option<u64> {
123	    None
124	}
125	
126	/// A cgroup hierarchy's mount: where it is mounted, and which of the hierarchy's directories is the mount's root
127	/// (`/` unless the mount is a bind mount of a subtree, as in a container).
128	#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
129	struct CgroupMount<'a> {
130	    point: String,
131	    root: &'a str,
132	}
133	
134	/// The mount of the cgroup v1 hierarchy with the `memory` controller (its super options list it, whether it is mounted
135	/// alone or beside `cpu,cpuacct`) and of the cgroup v2 hierarchy, from `/proc/self/mountinfo`. A line that is not
136	/// well formed is skipped.
137	#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
138	fn cgroup_mounts(mountinfo: &str) -> (Option<CgroupMount<'_>>, Option<CgroupMount<'_>>) {
139	    let (mut v1, mut v2) = (None, None);
140	    for line in mountinfo.lines() {
141	        let fields: Vec<&str> = line.split_whitespace().collect();
142	        // The optional fields end at the `-`, which cannot come before the sixth field.
143	        let Some(dash) = fields.iter().skip(5).position(|field| *field == "-").map(|at| at + 5) else { continue };
144	        let (Some(root), Some(point), Some(kind)) = (fields.get(3), fields.get(4), fields.get(dash + 1)) else {
145	            continue;
146	        };
147	        let mount = || CgroupMount { point: unescape(point), root };
148	        match *kind {
149	            "cgroup2" if v2.is_none() => v2 = Some(mount()),
150	            "cgroup" if v1.is_none() => {
151	                let options = fields.get(dash + 3).copied().unwrap_or_default();
152	                if options.split(',').any(|option| option == "memory") {
153	                    v1 = Some(mount());
154	                }
155	            }
156	            _ => {}
157	        }
158	    }
159	    (v1, v2)
160	}
161	
162	/// A mountinfo path with its octal escapes (`\040` for a space) decoded.
163	#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
164	fn unescape(path: &str) -> String {
165	    let (bytes, mut out, mut at) = (path.as_bytes(), Vec::with_capacity(path.len()), 0);
166	    while at < bytes.len() {
167	        let octal = bytes.get(at + 1..at + 4).filter(|_| bytes[at] == b'\\');
168	        match octal.and_then(|digits| u8::from_str_radix(std::str::from_utf8(digits).ok()?, 8).ok()) {
169	            Some(byte) => {
170	                out.push(byte);
171	                at += 4;
172	            }
173	            None => {
174	                out.push(bytes[at]);
175	                at += 1;
176	            }
177	        }
178	    }
179	    String::from_utf8_lossy(&out).into_owned()
180	}
181	
182	/// The files that hold the memory limits of the cgroups `/proc/self/cgroup` (`own`) lists, each cgroup's and every
183	/// ancestor's up to the root of its mount: cgroup v2's `memory.max` (the `0::` line) and cgroup v1's
184	/// `memory.limit_in_bytes` (the line whose controllers include `memory`), each under the mount point `mountinfo` gives
185	/// for that hierarchy ([`cgroup_mounts`]). The process's cgroup path is relative to the hierarchy's root, so a mount
186	/// whose root is a subtree shows only the cgroups under it, and a cgroup outside it has no files. A hierarchy with no
187	/// mount has none.
188	#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
189	fn limit_files(own: &str, mountinfo: &str) -> Vec<String> {
190	    let (v1, v2) = cgroup_mounts(mountinfo);
191	    let mut files = Vec::new();
192	    for line in own.lines() {
193	        let mut fields = line.splitn(3, ':');
194	        let (Some(_), Some(controllers), Some(path)) = (fields.next(), fields.next(), fields.next()) else { continue };
195	        let (mount, file) = match controllers {
196	            "" => (&v2, "memory.max"),
197	            _ if controllers.split(',').any(|controller| controller == "memory") => (&v1, "memory.limit_in_bytes"),
198	            _ => continue,
199	        };
200	        let Some(mount) = mount else { continue };
201	        let root = mount.root.trim_end_matches('/');
202	        let path = path.trim_end_matches('/');
203	        let Some(mut dir) = path.strip_prefix(root).filter(|rest| rest.is_empty() || rest.starts_with('/')) else {
204	            continue;
205	        };
206	        let point = mount.point.trim_end_matches('/');
207	        loop {
208	            files.push(format!("{point}{dir}/{file}"));
209	            match dir.rfind('/') {
210	                Some(parent) => dir = &dir[..parent],
211	                None => break,
212	            }
213	        }
214	    }
215	    files
216	}
217	
218	/// A cgroup memory limit file's bytes; none for no limit: `max` (v2), or a value past 2^60 (v1 writes about 2^63 for
219	/// no limit).
220	#[cfg_attr(not(target_os = "linux"), allow(dead_code))]
221	fn parse_limit(text: &str) -> Option<u64> {
222	    text.trim().parse::<u64>().ok().filter(|bytes| *bytes < 1 << 60)
223	}
224	
225	tokio::task_local! {
226	    /// The watch of the run the current task answers for ([`step`]). A task outside a run's lanes has none, and is never
227	    /// stopped.
228	    pub(crate) static HEAP: std::sync::Arc<Watch>;
229	}
230	
231	/// One step of the run the current task answers for: a checker request, or a type converted or recalled. Refused once
232	/// the run's heap is past its budget.
233	pub(crate) fn step() -> Result<(), CallError> {
234	    match HEAP.try_with(|watch| watch.allows_step()) {
235	        Ok(false) => Err(CallError::OverBudget),
236	        Ok(true) | Err(_) => Ok(()),
237	    }
238	}
239	
240	/// One run's reading of its heap against its budget, shared by its lanes. Once past, it stays past.
241	pub(crate) struct Watch {
242	    budget: Option<HeapBudget>,
243	    steps: AtomicU64,
244	    peak: AtomicU64,
245	    /// The heap the read that found it past the budget saw.
246	    held: OnceLock<u64>,
247	}
248	
249	impl Watch {
250	    /// A watch over `budget`; with none, the run is never stopped and the heap never read.
251	    pub(crate) fn new(budget: Option<HeapBudget>) -> Self {
252	        Self { budget, steps: AtomicU64::new(0), peak: AtomicU64::new(0), held: OnceLock::new() }
253	    }
254	
255	    /// Reads the heap; whether it is past the budget, now or before.
256	    pub(crate) fn past(&self) -> bool {
257	        let Some(budget) = self.budget else { return false };
258	        if self.held.get().is_some() {
259	            return true;
260	        }
261	        let held = (budget.meter)();
262	        self.peak.fetch_max(held, Ordering::Relaxed);
263	        if held > budget.bytes {
264	            self.held.get_or_init(|| held);
265	            return true;
266	        }
267	        false
268	    }
269	
270	    /// Whether the heap was found past the budget, without reading it.
271	    pub(crate) fn passed(&self) -> bool {
272	        self.held.get().is_some()
273	    }
274	
275	    /// Whether the run may take one more step: not once the heap is past the budget, which every [`STEPS_PER_READ`]th
276	    /// step reads.
277	    fn allows_step(&self) -> bool {
278	        if self.budget.is_none() {
279	            return true;
280	        }
281	        if self.passed() {
282	            return false;
283	        }
284	        let taken = self.steps.fetch_add(1, Ordering::Relaxed);
285	        !(taken.is_multiple_of(STEPS_PER_READ) && self.past())
286	    }
287	
288	    /// The most the heap held at a read, in bytes; 0 when it was never read.
289	    pub(crate) fn peak(&self) -> u64 {
290	        self.peak.load(Ordering::Relaxed)
291	    }
292	
293	    /// The one warning for the components `left` structural once the heap was past the budget; none when it never
294	    /// was, or nothing was left.
295	    pub(crate) fn diagnostic(&self, mut left: Vec<String>) -> Option<Diagnostic> {
296	        let (Some(budget), Some(held)) = (self.budget, self.held.get()) else { return None };
297	        if left.is_empty() {
298	            return None;
299	        }
300	        left.sort();
301	        let mut diagnostic = Diagnostic::new(
302	            DiagnosticSeverity::Warning,
303	            DiagnosticCode::SemanticBackend,
304	            format!(
305	                "{} component(s) kept their structural result: the heap held {} MiB, past this run's {} MiB budget, \
306	                 so the TypeScript checker was asked nothing more. Which components the checker had answered by then \
307	                 depends on timing, so this output can differ from run to run",
308	                left.len(),
309	                held >> 20,
310	                budget.bytes >> 20
311	            ),
312	        )
313	        .with_help(
314	            "The budget is 60% of the memory this process may use (the machine's, or its cgroup limit on Linux), at most 8 GiB. A type that expands to millions of members, \
315	             such as a style system declared in the project's own source, is the usual cause; `--no-checker` gives \
316	             the structural result for every component.",
317	        );
318	        diagnostic.affects = left;
319	        Some(diagnostic)
320	    }
321	}
322	
323	#[cfg(test)]
324	mod tests {
325	    use super::*;
326	
327	    const V2: &str = "29 22 0:26 / /sys/fs/cgroup rw,nosuid,nodev,noexec,relatime - cgroup2 cgroup2 rw,nsdelegate\n";
328	    const V1_COMOUNTED: &str = "30 23 0:27 / /sys/fs/cgroup/cpu,cpuacct,memory rw,nosuid,relatime shared:12 - cgroup cgroup rw,cpu,cpuacct,memory\n";
329	    const V1_SEPARATE: &str = "31 23 0:28 / /sys/fs/cgroup/cpu,cpuacct rw,relatime - cgroup cgroup rw,cpu,cpuacct\n\
330	                               32 23 0:29 / /sys/fs/cgroup/memory rw,relatime - cgroup cgroup rw,memory\n";

